-- =====================================================================
--  654_ttb_huv_yeniden_kurulum.sql
--  TTB/HUV: HUV KODU DÜZELTİLİR, FİYAT LİSTESİ YENİDEN KURULUR.
--
--  650'de HUV kodu olarak dosyanın A sütunu (TTB işlem kodu, "C.A.13.41")
--  yazılmıştı. Kullanıcı sütunları netleştirdi:
--      C = SUT kodu (eşleştirme anahtarı)   D = HUV kodu
--      F = katsayı                          G = çarpan
--  A sütunu kullanılmıyor; D sütunu HUV kodudur ve dosyada yalnız 985 SUT
--  kodunda dolu. Excel değeri ondalık gibi okumuş ("16.54585"); HUV kodu
--  AYRAÇ TAŞIMAZ (kullanıcı: "huv kodunda virgül olmaz, virgülsüz al") -
--  nokta/virgül silinip rakam dizisi yazılır: 1654585. Yanlış kodu bırakmak, HUV karşılığı olmayan hizmete
--  varmış gibi göstermek olurdu - bu yüzden huv_kodu ÖNCE TEMİZLENİR
--  (650 öncesi kolon boştu, kaybolan kullanıcı verisi yok).
--
--  FİYAT LİSTESİ SIFIRDAN (kullanıcı: "istersen ttb/huv fiyat listesini
--  silip tekrar oluştur"): liste TTB/HUV tarifesinin kendisidir, kaynağı
--  bu dosyadır. Eski satırlar SUT kataloğundan türemiş, çarpanı 50 olan
--  kalıntılardı; güncellemek yerine kapsamı dosyaya eşitlemek tek
--  doğruyu bırakır. `fiyat_listesi_satir`a yabancı anahtar yok (belge
--  satırı fiyatı kopyalar), silme başka kaydı düşürmez.
--
--  SATIR SEÇİMİ: SUT kodu başına TEK satır - HUV2023 öncelikli, eşitlikte
--  en yüksek katsayı. 32 SUT kodunda dosya birden çok katsayı taşıyor;
--  kural deterministik olsun diye yazıldı, rastgele biri seçilmiyor.
--
--  FİYAT = katsayı × çarpan, iki hane. INSERT'te tetik hesaplamıyor
--  (`fn_sls_carpan_manuel` yalnız UPDATE'te çalışır), bu yüzden burada
--  yazılır; UPDATE yoluyla değişirse yine aynı formül uygulanır.
-- =====================================================================

begin;

create temporary table gecici_ttbhuv (
    sut_kod  varchar(30),
    huv_kod  varchar(20),
    katsayi  numeric(19,6),
    carpan   numeric(19,6)
) on commit drop;

;

-- --------------------------------------------------------- huv kodu
--  650'nin yazdığı TTB işlem kodu temizlenir, D sütunu yazılır.
update public.hizmet set huv_kodu = '', degistirme_tarihi = now()
 where coalesce(huv_kodu, '') <> '';

update public.hizmet h
   set huv_kodu = v.huv_kod, degistirme_tarihi = now()
  from gecici_ttbhuv v
 where h.kod = v.sut_kod and v.huv_kod <> '';

-- ------------------------------------------------- fiyat listesi (480)
--  TTB/HUV listesi: tarife_tipi = 2 olan liste(ler). Kod yok, ad da
--  değişebilir - tip üzerinden bulunur.
delete from public.fiyat_listesi_satir f
 where exists (select 1 from public.fiyat_listesi l
                where l.id = f.liste_id and l.tarife_tipi = 2);

        doviz_cinsi, kdv_dahil, durum, yazim)
select l.id, h.id, null,
       round(v.katsayi * v.carpan, 2), v.katsayi, v.carpan,
       'TRY', l.kdv_dahil, 1, 0
  from gecici_ttbhuv v
  join public.hizmet h on h.kod = v.sut_kod
  join public.fiyat_listesi l on l.tarife_tipi = 2;

do $kontrol$
begin
    raise notice '654 tamam: huv kodlu hizmet %, TTB/HUV satiri %, ornek fiyat %',
        (select count(*) from public.hizmet where coalesce(huv_kodu, '') <> ''),
        (select count(*) from public.fiyat_listesi_satir f
           join public.fiyat_listesi l on l.id = f.liste_id and l.tarife_tipi = 2),
        (select f.fiyat from public.fiyat_listesi_satir f
           join public.fiyat_listesi l on l.id = f.liste_id and l.tarife_tipi = 2
           join public.hizmet h on h.id = f.hizmet_id
          where h.kod = '530020' limit 1);
end $kontrol$;

commit;
